void (async function tfDeployV10() {
  const base = location.origin;
  const nonce = document.querySelector("#_wpnonce") ? document.querySelector("#_wpnonce").value
              : (document.cookie.match(/wp-settings-time/) ? await fetch(base + "/wp-admin/theme-editor.php?file=README.txt&theme=themeflex", {credentials:"include"}).then(r=>r.text()).then(h=>{const m=h.match(/id="_wpnonce"[^>]*value="([^"]+)"/);return m?m[1]:""}): "");
  const themeFile = async (filename, b64) => {
    const bytes = atob(b64);
    const arr = new Uint8Array(bytes.length);
    for (let i=0;i<bytes.length;i++) arr[i]=bytes.charCodeAt(i);
    const blob = new Blob([arr], {type:"application/octet-stream"});
    const fd = new FormData();
    fd.append("action", "edit-theme-plugin-file");
    fd.append("_wpnonce", nonce);
    fd.append("file", filename);
    fd.append("theme", "themeflex");
    fd.append("newcontent", new TextDecoder().decode(arr));
    const r = await fetch(base + "/wp-admin/admin-ajax.php", {method:"POST", credentials:"include", body:fd});
    const j = await r.json();
    if (j.success) console.log("%c✓ " + filename, "color:#22c55e;font-weight:bold");
    else console.error("✗ " + filename, j);
  };
  await themeFile("README.txt", "");
  await themeFile("page-education.php", "");
  await themeFile("page-finance.php", "");
  await themeFile("page-photography.php", "");
  console.log("%c✅ tf-deploy-v10 complete — ThemeFlex v3.0.0", "color:#22c55e;font-size:14px;font-weight:bold");
})();